from register.models import *
from datetime import *
from transaction.models import *


def Level(u):
	m=Register.objects.get(k_id=u).birthdate.replace(tzinfo=None).date()
	adate=datetime.now().date()
	h=int((adate - m).days / 365)
	if h < 4:
		return 0
	if h >= 4 and h <=5:
		return 1
	if h >= 6 and h <=7:
		return 2
	if h >= 8 and h <=9:
		return 3
	if h >= 10 and h <=13:
		return 4

def Service():
	c=datetime.now()
	if c.strftime("%A") == 'Sunday':
		if c.time() >= time(9, 30, 0) and c.time() <= time(11, 00, 0):
			return 1
		elif c.time() >= time(12, 30, 0) and c.time() <= time(14, 30, 0):
			return 2
		elif c.time() >= time(15, 00, 0) and c.time() <= time(17, 0, 0):
			return 3
		elif c.time() >= time(17,30, 0) and c.time() <= time(19, 30, 0):
			return 4
		else:
			return 255
	else:
		return 0

def xService(u):
	if u.strftime("%A") == 'Sunday':
		if u.time() >= time(9, 30, 0) and u.time() <= time(11, 00, 0):
			return 1
		elif u.time() >= time(12, 30, 0) and u.time() <= time(14, 30, 0):
			return 2
		elif u.time() >= time(15, 00, 0) and u.time() <= time(17, 0, 0):
			return 3
		elif u.time() >= time(17,30, 0) and u.time() <= time(18, 45, 0):
			return 4
		else:
			return 255
	else:
		return 0

def InOut(u):
	if Transaction.objects.filter(register_id=u).last():
		if Transaction.objects.filter(register_id=u).last().tdate.date() == datetime.now().date():
			if Transaction.objects.filter(tdate__date=datetime.now().date(), register_id=u).last().status == '1':
				return 0
			else:
				return 1
		else:
			return 1
	else:
		return 1

def service_chk(u):
	if Transaction.objects.filter(register_id=u).last():
		if Transaction.objects.filter(register_id=u).last().tdate.date() == datetime.now().date():
			if Transaction.objects.filter(tdate__date=datetime.now().date(), register_id=u).last().status == '1':
				s=Transaction.objects.filter(tdate__date=datetime.now().date(), register_id=u).last().service
				return s
			else:
				return Service()
		else:
			return Service()
	else:
		return Service()


def records(u):
	k={}
	for i in Transaction.objects.filter(register_id=Register.objects.get(k_id=u).id):
		if i.tdate.date() not in k:
			k[i.tdate.date()]={}
			if 'status' not in k[i.tdate.date()]: 
				k[i.tdate.date()]['status']={}
				if i.status not in k[i.tdate.date()]['status']:
					k[i.tdate.date()]['status'][i.status]=[]
					k[i.tdate.date()]['status'][i.status].append(i.tdate.time())
			else:
				k[i.tdate.date()]['status'][i.status].append(i.tdate.time())
		else:
			if i.status not in k[i.tdate.date()]['status']:
				k[i.tdate.date()]['status'][i.status]=[]
				k[i.tdate.date()]['status'][i.status].append(i.tdate.time())
			else:
				k[i.tdate.date()]['status'][i.status].append(i.tdate.time())
	j={}
	for i in k:
		j[i]={}
		for x in k[i]:
			for g in k[i][x]:
				if g == '1':	
					j[i]['1']=min(k[i][x][g])
				else:
					j[i]['0']=max(k[i][x][g])
	for i in j:
		if '0' not in j[i]:
			j[i]['0']=0
		if '1' not in j[i]:
			j[i]['1']=0
	return j	
